.enhanced-text {
  font-feature-settings: "liga" 1, "kern" 1, "onum" 1;
  /* Shorthand for common features (supported by many browsers): */
  /* font-variant-ligatures: common-ligatures; */
  /* font-variant-numeric: oldstyle-nums; */
}

/* Example for specific feature application */
.drop-cap {
  font-feature-settings: "dlig" 1; /* Discretionary ligatures */
  /* This often requires a font that specifically supports it */
}

/* For browsers that support the more semantic font-variant properties */
h1 {
  font-variant-ligatures: common-ligatures contextual;
  font-variant-numeric: oldstyle-nums slashed-zero;
  font-variant-caps: small-caps;
}
